}
.zq-panel header,
.zq-account footer {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  align-items: center;
}
.zq-panel h1 {
  font-size: 18px;
  font-weight: 600;
  margin: 0 0 4px;
}
.zq-panel h2 {
  font-size: 14px;
  font-weight: 600;
  margin: 0;
}
.zq-panel p {
  color: var(--muted-foreground);
  margin: 6px 0;
  line-height: 1.6;
}
.zq-panel button,
.zq-panel input,
.zq-panel select {
  height: 28px;
  border: 0;
  border-radius: 6px;
  background: var(--muted);
  color: var(--foreground);
  padding: 0 9px;
}
.zq-panel button {
  cursor: pointer;
}
.zq-panel button:disabled {
  opacity: 0.45;
  cursor: default;
}
.zq-panel form {
  margin: 20px 0;
}
.zq-content {
  max-width: 760px;
  margin: 0 auto;
}
.zq-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}
.zq-panel form {
  max-width: 480px;
  padding: 16px;
  background: var(--card, var(--muted));
  border-radius: 8px;
}
.zq-form {
  display: grid;
  grid-template-columns: 1fr 2fr;
  gap: 12px;
  margin: 14px 0;
}
.zq-form label {
  display: flex;
  flex-direction: column;
  gap: 6px;
  color: var(--muted-foreground);
  min-width: 0;
}
.zq-form input,
.zq-form select {
  width: 100%;
  box-sizing: border-box;
  min-width: 0;
}
.zq-path {
  grid-column: 1 / -1;
}
.zq-panel .zq-primary {
  background: var(--accent, var(--foreground));
  color: var(--accent-foreground, var(--background));
}
.zq-details {
  margin-top: 16px;
  max-width: 480px;
  color: var(--muted-foreground);
  font-size: 11px;
}
.zq-details summary {
  cursor: pointer;
}
.zq-help {
  font-size: 11px;
  max-width: 900px;
}
.zq-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 280px), 1fr));
  gap: 12px;
  margin: 20px 0;
}
.zq-account {
  padding: 16px;
  background: color-mix(in srgb, var(--muted) 40%, transparent);
  border-radius: 8px;
}
.zq-window {
  margin-top: 20px;
}
.zq-window > div {
  display: flex;
  justify-content: space-between;
  gap: 8px;
}
.zq-window progress {
  width: 100%;
  height: 6px;
  margin-top: 7px;
  accent-color: var(--accent, var(--foreground));
}
.zq-window p,
.zq-account footer {
  font-size: 11px;
  color: var(--muted-foreground);
}
.zq-account footer {
  margin-top: 20px;
}
.zq-panel [role=alert] {
  color: var(--destructive);
}
.zq-empty {
  padding: 30px 0;
}
.zq-panel :focus-visible {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
.zq-connect {
  padding: 20px;
  border-radius: 10px;
  background: var(--card, var(--muted));
}
.zq-connect p {
  margin: 8px 0 20px;
}
.zq-panel .zq-subtle {
  padding: 0;
  background: transparent;
  color: var(--muted-foreground);
}
.zq-window strong {
  font-size: 18px;
  font-weight: 600;
}
.zq-account {
  min-width: 0;
}
.zq-account [role=alert] {
  overflow-wrap: anywhere;
}

